root.command:

IF OBJECT_ID(N'dbo.PeopleTbl', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.PeopleTbl', N'DeliveryType') IS NULL
BEGIN
    ALTER TABLE dbo.PeopleTbl ADD DeliveryType VARCHAR(10) NOT NULL
        CONSTRAINT DF_PeopleTbl_DeliveryType DEFAULT ('NONE');

    EXEC (N'UPDATE dbo.PeopleTbl SET DeliveryType = ''DELIVER''
            WHERE UPPER(LTRIM(RTRIM(Abbreviation))) IN (N''SQ'', N''WM'', N''MX'');
            UPDATE dbo.PeopleTbl SET DeliveryType = ''COLLECT''
            WHERE UPPER(LTRIM(RTRIM(Abbreviation))) IN (N''CLLCT'', N''COLL'', N''COLLECT'')
               OR Person LIKE N''%collect%'';');

    IF COL_LENGTH(N'dbo.PeopleTbl', N'IsDispatched') IS NOT NULL
        EXEC (N'UPDATE dbo.PeopleTbl SET DeliveryType = ''COURIER'' WHERE IsDispatched = 1;');
END
